// ─── Public API ──────────────────────────────────────────────────────────────

/**
 * Returns city + country for a given IATA code, or null if unknown.
 * Input is case-insensitive.
 *
 * @example
 *   getAirportInfo('dxb') // → { city: 'Dubai', country: 'UAE' }
 */
export function getAirportInfo(code: string): AirportInfo | null {
  if (!code) return null;
  return AIRPORT_MAP[code.toUpperCase().trim()] ?? null;
}

/**
 * Returns a formatted "City, Country" string, or null if the code is unknown.
 *
 * @example
 *   getAirportLabel('LHR') // → 'London Heathrow, UK'
 *   getAirportLabel('XYZ') // → null
 */
export function getAirportLabel(code: string): string | null {
  const info = getAirportInfo(code);
  if (!info) return null;
  return info.country ? `${info.city}, ${info.country}` : info.city;
}
